import { View, StyleSheet, TextInput } from 'react-native'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import {
	HeaderBar,
	Button,
	SecretItem,
	type Secret,
	type Environment,
	AnimatedFlatList,
	SearchBarContainer,
	SearchBarOverlay
} from '@/components'
import { router, useLocalSearchParams } from 'expo-router'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import { useRef, useState } from 'react'
import { EmptyStateContainer } from '@/screens/home/components/EmptyStateContainer'
import Animated, { LinearTransition } from 'react-native-reanimated'
import {
	SecretFilter,
	secretFilterConfigs,
	useSecretFilterStore
} from '../state/secretFilters'
import {
	DeleteSecretBottomSheet,
	DeleteSecretBottomSheetRef
} from '@/screens/project/components/DeleteSecretBottomSheet'
import {
	useGetProjectGroupSecretsQuery,
	useDeleteSecretMutation,
	CreateEnvironment
} from '@/generated/graphql'

const mapApiEnvironmentToLocal = (env: CreateEnvironment): Environment => {
	switch (env) {
		case CreateEnvironment.DEVELOPMENT:
			return 'Builder'
		case CreateEnvironment.PREVIEW:
			return 'Preview'
		case CreateEnvironment.PRODUCTION:
			return 'Published'
	}
}

export const ProjectSecretSettingsScreen = () => {
	const { theme } = useTheme()
	const insets = useSafeAreaInsets()
	const filterStore = useSecretFilterStore()
	const { hasFilter } = filterStore

	const { projectGroupId } = useLocalSearchParams<{ projectGroupId?: string }>()

	const { data, loading, refetch } = useGetProjectGroupSecretsQuery({
		variables: {
			projectGroupId: projectGroupId!,
			first: 100
		},
		skip: !projectGroupId
	})

	const [deleteSecret] = useDeleteSecretMutation({
		refetchQueries: ['GetProjectGroupSecrets'],
		onError: (error) => {
			console.error('Failed to delete secret:', error)
		}
	})

	const secrets: Secret[] = (() => {
		const nodes = data?.projectGroupById?.secrets?.nodes ?? []
		return nodes.map((secret) => ({
			id: secret.id,
			name: secret.displayName,
			value: secret.value ?? '',
			dateAdded: secret.createdAt,
			environments: [mapApiEnvironmentToLocal(secret.environment)]
		}))
	})()

	const deleteBottomSheetRef = useRef<DeleteSecretBottomSheetRef>(null)
	const [expandedCount, setExpandedCount] = useState(0)

	const [searchValue, setSearchValue] = useState('')
	const [isSearchBarOpen, setIsSearchBarOpen] = useState(false)
	const searchInputRef = useRef<TextInput>(null)

	const onClose = () => {
		router.back()
	}

	const handleAddSecret = () => {
		router.push({
			pathname: '/project/project-add-secret',
			params: {
				projectGroupId
			}
		})
	}

	const handleOpenDeleteSheet = (id: string) => {
		deleteBottomSheetRef.current?.open(id)
	}

	const handleDeleteSecret = (id: string) => {
		deleteSecret({
			variables: {
				input: {
					id
				}
			}
		})
		deleteBottomSheetRef.current?.close()
	}

	const filteredSecrets = (() => {
		let filtered = secrets

		if (searchValue.trim()) {
			const query = searchValue.toLowerCase()
			filtered = filtered.filter(
				(secret) =>
					secret.name.toLowerCase().includes(query) ||
					secret.value.toLowerCase().includes(query)
			)
		}

		if (filterStore.filtersCount > 0) {
			filtered = filtered.filter((secret) => {
				const hasPublished =
					hasFilter(SecretFilter.PUBLISHED) &&
					secret.environments.includes('Published')
				const hasPreview =
					hasFilter(SecretFilter.PREVIEW) &&
					secret.environments.includes('Preview')
				const hasBuilder =
					hasFilter(SecretFilter.BUILDER) &&
					secret.environments.includes('Builder')
				return hasPublished || hasPreview || hasBuilder
			})
		}

		return filtered
	})()

	const ItemSeparatorComponent = () => {
		return (
			<Animated.View
				style={styles.itemSeparator(theme)}
				layout={LinearTransition}
			/>
		)
	}

	const handleExpandedChange = (id: string, isExpanded: boolean) => {
		setExpandedCount((prev) => Math.max(0, prev + (isExpanded ? 1 : -1)))
	}

	return (
		<View
			style={[
				styles.container(theme),
				{
					paddingTop: insets.top
				}
			]}
		>
			<SearchBarOverlay
				isSearchBarOpen={isSearchBarOpen}
				setIsSearchBarOpen={setIsSearchBarOpen}
				searchInputRef={searchInputRef}
				searchValue={searchValue}
				setSearchValue={setSearchValue}
				placeholder="Search secrets"
				storageKey="secret-search-history"
			/>

			<HeaderBar title="Secrets" onClose={onClose} showBackButton />

			<View style={styles.searchBarContainer(theme)}>
				<SearchBarContainer
					searchInputRef={searchInputRef}
					setIsSearchBarOpen={setIsSearchBarOpen}
					searchValue={searchValue}
					setSearchValue={setSearchValue}
					placeholder="Search secrets"
					filterConfigs={secretFilterConfigs}
					filterStore={filterStore}
				/>
			</View>

			<View style={styles.contentContainer}>
				<AnimatedFlatList
					itemLayoutAnimation={LinearTransition}
					contentContainerStyle={{
						flexGrow: 1
					}}
					style={styles.list}
					contentInset={{
						bottom: insets.bottom + 32 + (expandedCount > 0 ? 48 : 0)
					}}
					scrollIndicatorInsets={{
						bottom: insets.bottom + 32
					}}
					ItemSeparatorComponent={ItemSeparatorComponent}
					ListEmptyComponent={
						<View style={{ flex: 1, marginBottom: '60%' }}>
							<EmptyStateContainer
								isShining={false}
								isEmpty={true}
								isRefreshing={loading}
								onRefresh={refetch}
								text={
									searchValue || filterStore.filtersCount > 0
										? 'No secrets match your filters'
										: 'No secrets found'
								}
							/>
						</View>
					}
					data={filteredSecrets}
					renderItem={({ item }) => (
						<SecretItem
							secret={item}
							onDelete={handleOpenDeleteSheet}
							onExpandedChange={handleExpandedChange}
						/>
					)}
				/>
			</View>

			<View
				style={[styles.buttonContainer, { paddingBottom: insets.bottom + 16 }]}
			>
				<Button text="Add new secret" onPress={handleAddSecret} />
			</View>
			<DeleteSecretBottomSheet
				bottomSheetRef={deleteBottomSheetRef}
				bottomInset={insets.bottom + 16}
				onDelete={handleDeleteSecret}
			/>
		</View>
	)
}

const styles = defineStyles({
	container: (theme: Theme) => ({
		flex: 1,
		backgroundColor: colors[theme].background,
		paddingHorizontal: 24
	}),
	searchBarContainer: (theme: Theme) => ({
		paddingVertical: 20,
		backgroundColor: colors[theme].background
	}),
	contentContainer: {
		flex: 1,
		marginHorizontal: -24
	},
	list: {},
	itemSeparator: (theme: Theme) => ({
		height: StyleSheet.hairlineWidth,
		backgroundColor: colors[theme].gray[75]
	}),
	buttonContainer: {
		paddingHorizontal: 20,
		position: 'absolute',
		bottom: 0,
		left: 0,
		right: 0
	}
})
